package io.github.jackotom.hongguo.android;
import java.net.SocketTimeoutException;import java.util.*;
/** Exercises complete production completion/load/bind callbacks; only platform/source/cache are doubles. */
public final class PlaybackAutoplayActivityTest {
 static int checks,groups;
 static void check(boolean v,String text){checks++;if(!v)throw new AssertionError(text);}
 static void group(String text){groups++;System.out.println("PASS "+text);}
 static AdaptiveActivityHarness fresh()throws Exception{PlaybackSources.reset();AdaptiveActivityHarness p=new AdaptiveActivityHarness();p.autoplay=true;p.quality="auto";p.actualQuality="auto";return p;}
 static void prepared(AdaptiveActivityHarness p){p.resolver.flush();p.main.flush();p.video.position=0;p.video.complete(576,1024);p.main.flush();}
 static void ended(AdaptiveActivityHarness p){p.video.playing=false;p.mediaPlayer.playing=false;p.video.position=180000;p.video.completion.complete(p.mediaPlayer);}
 public static void main(String[]args)throws Exception {
  AdaptiveActivityHarness p=fresh();p.requestedSpeed=1.5f;p.loadAt(0,null,0);prepared(p);check(p.current==0&&p.prepared&&p.video.playing,"first episode starts");int token=p.generation;ended(p);check(p.current==1&&p.generation==token+1&&!p.prepared&&!p.userPaused&&!p.completed,"completion selects next immediately with new playback intent");prepared(p);check(p.current==1&&p.prepared&&p.video.playing&&p.actualSpeed==1.5f,"next episode prepares and actually starts at retained speed");check(p.store.histories.contains("v1:0")&&p.store.histories.contains("v2:0"),"old completion and new start preserve identities");group("real completion callback advances and starts next episode without another click");
  ended(p);prepared(p);check(p.current==2&&p.video.playing,"second completion starts third");int reads=PlaybackSources.calls.size();ended(p);p.pump();check(p.current==2&&p.completed&&!p.video.playing&&PlaybackSources.calls.size()==reads,"last episode stops without wrapping or fetching unknown season");check(p.currentKind.equals("本剧已播完"),"last episode gives final status");group("three-episode chain ends finitely at the same-season tail");
  AdaptiveActivityHarness disabled=fresh();disabled.autoplay=false;disabled.loadAt(0,null,0);prepared(disabled);ended(disabled);disabled.pump();check(disabled.current==0&&disabled.completed&&PlaybackSources.calls.size()==1,"autoplay off stays on finished episode");check(disabled.currentKind.contains("可点击下一集"),"manual-next state remains explicit");group("disabled autoplay never silently advances");
  AdaptiveActivityHarness late=fresh();late.loadAt(0,null,0);prepared(late);VideoView.Completion previous=late.video.completion;MediaPlayer old=late.mediaPlayer;ended(late);int next=late.generation;previous.complete(old);check(late.current==1&&late.generation==next,"duplicate old completion cannot skip second episode");prepared(late);previous.complete(old);check(late.current==1&&late.video.playing&&late.errors==0,"old completion remains inert after second prepared");group("late duplicate completion cannot skip or stop the selected next episode");
  AdaptiveActivityHarness failed=fresh();failed.loadAt(0,null,0);prepared(failed);for(String q:new String[]{"auto","720p","480p","360p"})PlaybackSources.failures.put(q,new SocketTimeoutException("fixture next source failed"));ended(failed);failed.pump();check(failed.current==1&&failed.errors==1&&!failed.prepared,"next-source exhaustion reports on next without silently skipping");check(PlaybackSources.calls.stream().noneMatch(s->s.contains("v3")),"failed second never resolves third");check(failed.pendingMedia.isEmpty(),"failed next releases temporary media");group("failed next source stays retryable on that episode instead of silently skipping");
  AdaptiveActivityHarness lower=fresh();lower.actualQuality="480p";lower.automaticCeiling=575;lower.requestedSpeed=2f;lower.loadAt(0,null,0);lower.resolver.flush();lower.main.flush();lower.video.complete(480,854);lower.main.flush();ended(lower);lower.resolver.flush();lower.main.flush();lower.video.complete(480,854);check(lower.current==1&&lower.video.playing&&lower.actualSpeed==2f&&lower.automaticCeiling==575,"next retains successful low contract and speed but not completion/pause");check(PlaybackSources.playbackRequests.contains("480p:575:false:false"),"next source has exact same strict cap");group("automatic low-quality contract and confirmed speed survive seamless next selection");
  AdaptiveActivityHarness cached=fresh();cached.loadAt(0,null,0);prepared(cached);cached.cacheWorker.flush();cached.main.flush();check(cached.cache.backgroundFetches.contains("v2:auto"),"prefetch completes for the following episode");cached.cache.hits.add("v2:auto");PlaybackSources.calls.clear();ended(cached);prepared(cached);check(cached.current==1&&cached.video.playing&&cached.currentCache,"completed next prefetch is playable locally");check(PlaybackSources.calls.isEmpty(),"completed prefetch does not request new next source");group("completion adopts a completed matching next-episode cache");
  AdaptiveActivityHarness racing=fresh();racing.loadAt(0,null,0);prepared(racing);PlaybackSources.onResolve=()->ended(racing);racing.cacheWorker.flush();racing.main.flush();check(racing.current==1&&!racing.prepared,"completion advances even while next prefetch source lookup is in progress");check(racing.caching.isEmpty(),"stale prefetch flight marker is released");prepared(racing);check(racing.current==1&&racing.video.playing&&racing.errors==0,"foreground next preparation wins obsolete prefetch");check(racing.cache.backgroundFetches.stream().noneMatch(s->s.startsWith("v2:")),"obsolete prior-generation prefetch cannot enqueue next transfer");group("completion during prefetch cannot deadlock or publish stale work");
  AdaptiveActivityHarness background=fresh();background.loadAt(0,null,0);prepared(background);ended(background);background.active=false;prepared(background);check(background.current==1&&background.prepared&&!background.video.playing&&!background.userPaused,"next prepared in background preserves intent without playing in background");background.active=true;check(!background.completed&&!background.userPaused,"foreground lifecycle can resume next instead of treating it as finished");group("background preparation retains a resumable next-episode state");
  System.out.println("PLAYBACK_AUTOPLAY_ACTIVITY_OK groups="+groups+" checks="+checks+" actualCompletion=true nextLoadBindAndPrepare=true prefetchDoneAndInFlight=true networkRequests=0");
 }
}
